using System;
using System.Collections;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;
namespace CiJing {
public sealed partial class GameApp {
 void ClickModalActionForTest(string name){var b=modal.GetComponentsInChildren<Button>().First(x=>x.GetComponentInChildren<Text>().text==name);ClickGuideForTest(b);}
 void ArrangeGardenForTest(bool flower){board.Load(Content.Levels[5]);UpdateSlots();int[] slots=flower?new[]{0,2,3,5}:new[]{0,2,4,4};int[] tonesToMove={2,2,4,4};for(int n=0;n<4;n++){int src=Array.FindIndex(board.cells,8,8,s=>!s.Empty&&s.tone==tonesToMove[n]);ClickSlotForTest(src);ClickSlotForTest(slots[n]);}}
 void ClickReturnSlotForTest(int index){Canvas.ForceUpdateCanvases();var rt=revisitLabels[index].rectTransform;var e=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(canvas.worldCamera,rt.TransformPoint(rt.rect.center))};var hits=new System.Collections.Generic.List<RaycastResult>();EventSystem.current.RaycastAll(e,hits);var slot=hits.Select(h=>h.gameObject.GetComponentInParent<RevisitSlot>()).FirstOrDefault(s=>s);if(!slot||slot.index!=index)throw new Exception("Return scene slot blocked "+index);ExecuteEvents.Execute(slot.gameObject,e,ExecuteEvents.pointerClickHandler);}
 IEnumerator JourneyTestOnly(){var dir=Path.Combine(Application.dataPath,"../Validation");Directory.CreateDirectory(dir);yield return new WaitForSeconds(.6f);yield return TestGardenJourney(dir);if(runtimeErrors>0)throw new Exception("Journey runtime errors "+runtimeErrors);Debug.Log("CIJING_JOURNEY_ONLY_PASS");yield return new WaitForSeconds(.3f);Application.Quit();}
 IEnumerator TestGardenJourney(string dir){
  save.gardenGuess=save.gardenRead=save.relics=save.revisited=0;LoadLevel(5);CloseModal();save.evidence[5]=1;var untouched=(Stone[])board.cells.Clone();AskBehindCurtain();yield return null;ClickModalActionForTest("花仍如昨");if(save.gardenGuess!=1||!board.cells.SequenceEqual(untouched))throw new Exception("Curtain guess changed puzzle");ObserveGarden();if(modal||solved)throw new Exception("Closed curtain could be inspected");ArrangeGardenForTest(false);Play();yield return new WaitForSeconds(6.1f);if(!gardenPending||solved)throw new Exception("World goal must wait for observation");Capture(Path.Combine(dir,"garden-before-observation.png"));board.Move(4,5);UpdateSlots();if(gardenPending)throw new Exception("Edited score reused old world result");ObserveGarden();yield return null;ClickModalActionForTest("再 听");board.Move(5,4);UpdateSlots();Play();yield return new WaitForSeconds(6.1f);ClickGuideForTest(gardenInspect);yield return null;Capture(Path.Combine(dir,"garden-seen-letter.png"));ClickModalActionForTest("将所见入卷");yield return new WaitForSeconds(.2f);if(!solved||save.gardenRead!=2||(save.relics&2)==0||!music.CadenceActive)throw new Exception("Observed letter route and cadence failed");yield return new WaitForSeconds(2.1f);CloseModal();
  ReadRelic(0);yield return null;Capture(Path.Combine(dir,"relic-new-wick.png"));if((save.relics&1)==0)throw new Exception("Changed wick not recorded");CloseModal();LoadLevel(5);CloseModal();yield return null;ArrangeGardenForTest(true);SeekScore(7);ObserveGarden();yield return null;ClickModalActionForTest("再 听");if(solved||save.gardenRead!=2)throw new Exception("Seek preview completed observation");Play();yield return new WaitForSeconds(6.1f);ClickGuideForTest(gardenInspect);yield return null;Capture(Path.Combine(dir,"garden-seen-flower.png"));ClickModalActionForTest("将所见入卷");yield return new WaitForSeconds(2.3f);CloseModal();if((save.gardenRead&3)!=3||(save.sceneOutcomes[5]&4)==0)throw new Exception("Both observations not preserved");
  AskBehindCurtain();yield return null;if(modal.GetComponentsInChildren<Button>().Any(b=>b.GetComponentInChildren<Text>().text=="花仍如昨"))throw new Exception("Past guess could be rewritten after observation");CloseModal();save.unlocked=Math.Max(save.unlocked,7);var main=(Stone[])board.cells.Clone();int progress=save.unlocked;for(int n=0;n<2;n++){ShowRevisits();yield return null;var b=modal.GetComponentsInChildren<Button>().First(x=>x.GetComponentInChildren<Text>().text.StartsWith(n==0?"溪亭 ·":"旧灯 ·"));ClickGuideForTest(b);yield return null;ClickReturnSlotForTest(n==0?9:8);ClickReturnSlotForTest(0);ClickReturnSlotForTest(n==0?8:9);ClickReturnSlotForTest(3);PlayRevisit();yield return new WaitForSeconds(5.9f);if((save.revisited&(1<<n))==0)throw new Exception("Return scene failed "+n);Capture(Path.Combine(dir,"revisit-"+n+".png"));CloseModal();if(!board.cells.SequenceEqual(main)||save.unlocked!=progress)throw new Exception("Return scene modified mainline");}
  ShowKeepsake();yield return null;Capture(Path.Combine(dir,"journey-keepsakes.png"));CloseModal();OpenRevisit(0);yield return null;ClickReturnSlotForTest(9);ClickReturnSlotForTest(0);PlayRevisit();CloseModal();yield return new WaitForSeconds(.9f);if(revisitOpen||revisitPlaying||voices.Any(v=>v.isPlaying))throw new Exception("Return scene escaped after close");
  LoadLevel(8);CloseModal();Sound(new Stone(1));yield return new WaitForSeconds(.25f);if(!waterVoice.isPlaying||Mathf.Abs(noteAir.cutoffFrequency-8500)>1)throw new Exception("Water acoustics missing");Silence();ShowStory(true);portrait.FinishLine();NextStory();if(storyDirection.prop.texture!=Resources.Load<Texture2D>("PropsInk/blossombranch"))throw new Exception("Reply did not carry the chosen branch");CloseModal();Persist();var data=JsonUtility.FromJson<SaveData>(File.ReadAllText(savePath));if(data.gardenRead!=3||data.revisited!=3||data.gardenGuess!=1)throw new Exception("Journey evidence did not persist");
  File.WriteAllText(Path.Combine(dir,"garden-journey-results.json"),"{\"passed\":true,\"outcomeGoals\":true,\"observationGate\":true,\"twoOutcomes\":true,\"guessAndCompare\":true,\"relics\":true,\"returnScenes\":2,\"isolatedReturns\":true,\"cadence\":true,\"waterAcoustics\":true,\"replyKeepsake\":true,\"save\":true}");Debug.Log("CIJING_GARDEN_JOURNEY_PASS outcome goals, observation, two routes, relics, two revisits, acoustics, cadence, reply, save");
 }
}
}
